file.specification:

// CONSTANTS (export these — consumed by EnergyMeter.tsx)
export const MAX_ENERGY = 300;
export const FRENZY_THRESHOLD = 150;
export const CATCHUP_THRESHOLD = 75;

// PRIME passive gain: +5 energy/sec
// PRIME chain cost: -10 (len 2-5), +10 (len 6), +20 (len 6 + wild used)
// FRENZY drain: -5/sec normal, -3/sec if energy < CATCHUP_THRESHOLD (catch-up)
// FRENZY chain gain: +10 always, +20 with wild (+2 bonus if catchup active)

export interface EnergyState {
  energy: number;               // 0-300, current player's local value
  globalMode: 'PRIME' | 'FRENZY';
  isAnchor: boolean;            // did this player trigger FRENZY?
  isCatchup: boolean;           // energy < CATCHUP_THRESHOLD during FRENZY
  isInstability: boolean;       // anchor dropped below 150, 2s warning active
}

export interface UseEnergyReturn extends EnergyState {
  applyChainEnergy: (chainLength: number, usedWild: boolean) => void;
  forceToFrenzy: () => void;    // Wild Scatter trigger
  onEnergyZero: (() => void) | null; // callback — fires once when energy hits 0
}

// Hook signature:
// useEnergy(globalMode: 'PRIME' | 'FRENZY', onGlobalModeChange: (mode: 'PRIME' | 'FRENZY') => void, onEnergyZero: () => void): UseEnergyReturn

// RAF loop implementation:
//   useRef for animationFrameId and lastTimestamp
//   On each frame: compute deltaSeconds from lastTimestamp
//   Apply passive gain or drain based on globalMode and energy value
//   Clamp energy to [0, MAX_ENERGY]
//   If energy crosses FRENZY_THRESHOLD upward and globalMode is PRIME:
//     call onGlobalModeChange('FRENZY'), set isAnchor = true
//   If energy hits 0: call onEnergyZero once (use ref flag to prevent multi-fire)
//   Cleanup: cancelAnimationFrame on unmount

// Input lock: applyChainEnergy must enforce 100ms minimum between calls.
// Use a ref timestamp for last chain time. If called within 100ms, ignore call.
// This is the anti-macro server-side rule mirrored client-side.

// Instability: when isAnchor and energy drops below FRENZY_THRESHOLD during FRENZY,
//   set isInstability = true, start a 2000ms timer.
//   If energy recovers above FRENZY_THRESHOLD within 2s: clear instability.
//   If timer expires and energy still below threshold: call onGlobalModeChange('PRIME').
